import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { PageHeader } from '@kerfjs/ui/page-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { ValueTable } from '@kerfjs/ui/value-table';
import { delegate } from './events';
import './shell.css';

type Pane = 'navigation' | 'workspace' | 'inspector';
export function createShell(root: HTMLElement, paint: (html: ReturnType<typeof Toolbar>) => void, preferences: { inspectorSize: number; saveInspectorSize(size: number): void }, navigate: (id: string) => void) {
  let selected = 'inbox';
  let phonePane: Pane = 'workspace';
  let size = Math.min(400, Math.max(200, preferences.inspectorSize || 260));
  const narrow = matchMedia('(max-width: 48rem)');
  let isNarrow = narrow.matches;
  const navigation = () => <aside class="shell-pane"><PageHeader title="Navigation" /><nav class="kui-sidebar kui-scroll-owner kui-section-stack" aria-label="Sections">
    <section class="kui-sidebar-section"><MenuHeader label="Workspace" /><MenuItem label="Inbox" itemId="inbox" action="shell-navigate" selected={selected === 'inbox'} /><MenuItem label="Tasks" itemId="tasks" action="shell-navigate" selected={selected === 'tasks'} /></section>
    <section class="kui-sidebar-section"><MenuHeader label="Organization" /><MenuItem label="People" itemId="people" action="shell-navigate" selected={selected === 'people'} /></section>
  </nav></aside>;
  const inspector = () => <aside class="shell-pane"><PageHeader title="Inspector" /><div class="kui-scroll-owner kui-pane-body"><ValueTable label="Selected item"><div><dt>Status</dt><dd>In review</dd></div><div><dt>Owner</dt><dd>Unassigned</dd></div></ValueTable></div></aside>;
  const workspace = () => <main class="shell-pane shell-main"><PageHeader title={selected === 'inbox' ? 'Inbox' : selected === 'tasks' ? 'Tasks' : 'People'} /><div class="kui-scroll-owner kui-pane-body kui-section-stack"><h2>Workspace overview</h2><p>Select a record to inspect its details.</p></div></main>;
  const render = () => <section class="shell app-root kui-layout">
    <Toolbar label="Application controls" leading={<ToolbarText text="Workspace" />} trailing={<ToolbarControlGroup label="Pane controls" appearance="borderless">{(['navigation', 'workspace', 'inspector'] as Pane[]).map(pane => <button class="app-button" type="button" data-action="shell-pane" data-pane={pane} aria-pressed={String(isNarrow && phonePane === pane)}>{pane === 'navigation' ? 'Navigation' : pane === 'workspace' ? 'Workspace' : 'Inspector'}</button>)}</ToolbarControlGroup>} />
    <div class="shell-body">{isNarrow ? (phonePane === 'navigation' ? navigation() : phonePane === 'inspector' ? inspector() : workspace()) : <><div class="shell-navigation">{navigation()}</div>{workspace()}<ResizableRegion id="workspace-inspector" label="Inspector width" size={size} min={200} max={400} edge="start">{inspector()}</ResizableRegion></>}</div>
  </section>;
  const repaint = () => paint(render());
  const offActions = delegate(root, 'click', '[data-action]', element => {
    if (element.dataset.action === 'shell-pane') { phonePane = element.dataset.pane as Pane; repaint(); }
    if (element.dataset.action === 'shell-navigate' && element.dataset.itemId) {
      selected = element.dataset.itemId; phonePane = 'workspace'; navigate(selected); repaint();
      root.querySelector<HTMLElement>('main h1, main h2')?.setAttribute('tabindex', '-1');
      root.querySelector<HTMLElement>('main h1, main h2')?.focus();
    }
  });
  // Controlled sizing; helper owns pointer drag and Arrow / Shift+Arrow / Home / End.
  const offResize = wireResizableRegions(root, {
    onResize: ({ id, size: next }) => { if (id === 'workspace-inspector') { size = next; repaint(); } },
    onCommit: ({ id, size: next }) => { if (id === 'workspace-inspector') preferences.saveInspectorSize(next); },
  });
  const onViewport = () => {
    const focusedPane = root.querySelector('aside:focus-within');
    if (focusedPane) phonePane = focusedPane.querySelector('nav') ? 'navigation' : 'inspector';
    isNarrow = narrow.matches; repaint();
  };
  narrow.addEventListener('change', onViewport);
  repaint();
  return { render, dispose() { offActions(); offResize(); narrow.removeEventListener('change', onViewport); } };
}

