button { font: inherit; }
.app-button { min-block-size: 2.25rem; padding: var(--kui-space-xs) var(--kui-space-s); color: var(--kui-color-text); background: var(--kui-color-surface); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); }
.app-button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
.app-button[data-primary] { color: var(--kui-color-brand-on-normal); background: var(--kui-color-brand-fill-normal); border-color: var(--kui-color-brand-border-normal); }
.app-root { min-inline-size: 0; color: var(--kui-color-text); background: var(--kui-color-surface); }
@media (prefers-reduced-motion: reduce) { .app-root { scroll-behavior: auto; } }

/* The application mount occupies the viewport; each visible pane owns one scroll region. */
html, body { margin: 0; block-size: 100%; overflow: hidden; }
.shell { block-size: 100dvh; display: grid; grid-template-rows: auto minmax(0, 1fr); overflow: hidden; }
.shell-body { min-inline-size: 0; min-block-size: 0; display: flex; }
.shell-pane { display: grid; block-size: 100%; min-inline-size: 0; min-block-size: 0; grid-template-rows: auto minmax(0, 1fr); }
.shell-main { flex: 1; }
.shell-navigation { flex: 0 0 14rem; min-block-size: 0; }
.shell-pane > .kui-scroll-owner { min-block-size: 0; overflow-wrap: anywhere; }
@media (max-width: 48rem) {
  .shell-body > .shell-pane { inline-size: 100%; }
  .shell .kui-toolbar { display: flex; height: auto; flex-wrap: wrap; gap: var(--kui-layout-control-gap); }
}
